{"type":"write_file","path":"components/Chat.tsx","content":""use client";

import { useState, useEffect, useRef } from 'react';
import MessageList from './MessageList';
import PromptInput from './PromptInput';
import EmptyState from './EmptyState';
import { cn } from '@/utils/cn';

type Message = {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
  isStreaming?: boolean;
};

export default function Chat() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [active, setActive] = useState(false);

  const addUserMessage = (text: string) => {
    const userMsg: Message = {
      id: Date.now().toString() + '-u',
      role: 'user',
      content: text,
      timestamp: Date.now(),
    };
    setMessages((prev) => [...prev, userMsg]);
  };

  const addAssistantMessage = (fullText: string) => {
    const id = Date.now().toString() + '-a';
    const placeholder: Message = {
      id,
      role: 'assistant',
      content: '',
      timestamp: Date.now(),
      isStreaming: true,
    };
    setMessages((prev) => [...prev, placeholder]);
    const words = fullText.split(' ');
    let i = 0;
    const interval = setInterval(() => {
      i++;
      setMessages((prev) =>
        prev.map((m) =>
          m.id === id ? { ...m, content: words.slice(0, i).join(' ') } : m,
        ),
      );
      if (i >= words.length) {
        clearInterval(interval);
        setMessages((prev) =>
          prev.map((m) => (m.id === id ? { ...m, isStreaming: false } : m)),
        );
      }
    }, 100);
  };

  const handleSend = (text: string) => {
    if (!text.trim()) return;
    addUserMessage(text);
    setActive(true);
    // Mock assistant response after short delay
    setTimeout(() => {
      const mock = `**Answer:**\n\nHere is some \`code\`:\n\n\`\`\`js\nconsole.log(\"Hello world\");\n\`\`\`\n\nAnd a list:\n- Item 1\n- Item 2`;
      addAssistantMessage(mock);
    }, 500);
  };

  return (
    <div className="flex-1 flex flex-col h-full">
      {active ? (
        <MessageList messages={messages} />
      ) : (
        <div className="flex-1 flex items-center justify-center empty-state-bg">
          <EmptyState onSubmit={handleSend} />
        </div>
      )}
      <PromptInput onSend={handleSend} />
    </div>
  );
}
"}}

{"type":"write_file","path":"components/MessageList.tsx","content":""use client";

import React, { useEffect, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { cn } from '@/utils/cn';
import { Copy } from 'lucide-react';
import Prism from 'prism-react-renderer';
import theme from 'prism-react-renderer/themes/vsDark';

type Message = {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
  isStreaming?: boolean;
};

interface Props {
  messages: Message[];
}

export default function MessageList({ messages }: Props) {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  return (
    <div className="flex-1 overflow-y-auto p-4 space-y-4">
      {messages.map((msg) => (
        <div
          key={msg.id}
          className={cn(
            'max-w-[80%] space-y-2',
            msg.role === 'user' ? 'ml-auto text-right' : 'mr-auto text-left',
          )}
        >
          <div
            className={cn(
              'inline-block p-3 rounded-2xl text-sm',
              msg.role === 'user'
                ? 'bg-neutral-800 text-white'
                : 'bg-neutral-700 text-white border border-neutral-600',
            )}
          >
            {msg.role === 'assistant' ? (
              <ReactMarkdown
                remarkPlugins={[remarkGfm]}
                components={{
                  code({ node, inline, className, children, ...props }) {
                    const match = /language-(\w+)/.exec(className || '');
                    const language = match ? match[1] : '';
                    return !inline && language ? (
                      <div className="relative rounded" >
                        <button
                          className="absolute right-2 top-2 p-1 bg-white/10 rounded"
                          onClick={() => {
                            navigator.clipboard.writeText(String(children).replace(/\n/g, ''));
                          }}
                          aria-label="Copy code"
                        >
                          <Copy size={14} className="text-white" />
                        </button>
                        <Prism
                          style={theme}
                          language={language}
                          PreTag="div"
                          {...props}
                        >
                          {String(children).replace(/\n$/, '')}
                        </Prism>
                      </div>
                    ) : (
                      <code className={cn('bg-neutral-800 px-1 py-0.5 rounded', className)} {...props}>
                        {children}
                      </code>
                    );
                  },
                }}
              >
                {msg.content}
              </ReactMarkdown>
            ) : (
              <span>{msg.content}</span>
            )}
          </div>
          <div className="text-xs text-gray-400">
            {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            {msg.isStreaming && <span className="ml-2 animate-pulse">▍</span>}
          </div>
        </div>
      ))}
      <div ref={bottomRef} />
    </div>
  );
}
"}}

{"type":"write_file","path":"components/PromptInput.tsx","content":""use client";
import { useState, useRef, useEffect } from 'react';
import { Send, Plus } from 'lucide-react';
import { cn } from '@/utils/cn';

interface Props {
  onSend: (text: string) => void;
}

export default function PromptInput({ onSend }: Props) {
  const [text, setText] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
      e.preventDefault();
      submit();
    } else if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      submit();
    }
  };

  const submit = () => {
    if (!text.trim()) return;
    onSend(text);
    setText('');
  };

  // Auto-resize textarea
  useEffect(() => {
    const el = textareaRef.current;
    if (el) {
      el.style.height = 'auto';
      el.style.height = Math.min(el.scrollHeight, 200) + 'px';
    }
  }, [text]);

  return (
    <div className="p-4 border-t border-neutral-800 bg-neutral-900 flex items-end gap-2">
      <button className="p-2 rounded-full bg-neutral-700 hover:bg-neutral-600" aria-label="Add attachment">
        <Plus size={20} />
      </button>
      <textarea
        ref={textareaRef}
        rows={1}
        value={text}
        onChange={(e) => setText(e.target.value)}
        onKeyDown={handleKeyDown}
        placeholder="Ask anything..."
        className="flex-1 bg-neutral-800 text-white rounded-2xl p-3 focus:outline-none focus:ring-2 focus:ring-neutral-500 resize-none"
      />
      <button
        onClick={submit}
        disabled={!text.trim()}
        className={cn(
          'p-2 rounded-full',
          text.trim() ? 'bg-blue-600 hover:bg-blue-500' : 'bg-neutral-600 cursor-not-allowed',
        )}
        aria-label="Send"
      >
        <Send size={20} className="text-white" />
      </button>
    </div>
  );
}
"}}

